      "title": "Feste und Traditionen",
      "text": "Letzte Woche war Amir an ein Stadtfest. Amir wollte eine Tradition erleben, kannte aber zuerst nicht alle Details. Deshalb fragte sie seine Tante nach Informationen. seine Tante erklärte ruhig, wie man sich vorbereiten kann.\n\nWährend der Aktivität beobachtete Amir die Menschen und fand eine praktische Lösung. Nicht alles lief wie geplant, trotzdem änderte sie den Plan ohne Stress. seine Tante fand es gut, dass Amir zuerst zuhörte und dann entschied.\n\nAm Ende erzählten beide, was sie gelernt hatten, und schrieben eine kurze Nachricht für die nächsten Besucher. Amir fand die Erfahrung hilfreich, weil sie neue Wörter gelernt und mehr Mut bekommen hatte.",
